//! Differential ratchet for
//! `src/engine/battleScriptRemainingHpToPowerOpcode.ts`. Expected complete
//! projections, controls, and exact missing-role errors are generated by
//! invoking the canonical TypeScript opcode handler; regenerate with `node
//! --experimental-strip-types
//! core-rs/tools/gen-battle-script-remaininghptopower-vectors.mjs`.

use std::collections::BTreeSet;

use factory_core::battle_script_remaininghptopower::{
    apply_battle_script_remaininghptopower, get_scaled_hp_fraction, remaining_hp_to_power,
    BattleScriptRemaininghptopowerBattler, BattleScriptRemaininghptopowerBattlerState,
    BattleScriptRemaininghptopowerControl, BattleScriptRemaininghptopowerRoles,
    BattleScriptRemaininghptopowerRules, BATTLE_SCRIPT_FLAIL_HP_SCALE_TO_POWER,
    BATTLE_SCRIPT_REMAININGHPTOPOWER_BATTLERS, BATTLE_SCRIPT_REMAININGHPTOPOWER_BATTLER_COUNT,
    BATTLE_SCRIPT_REMAININGHPTOPOWER_SCALE,
};
use factory_core::battle_script_remaininghptopower_vectors_gen::{
    BattleScriptRemaininghptopowerVectorCase, BattleScriptRemaininghptopowerVectorState,
    BATTLE_SCRIPT_REMAININGHPTOPOWER_BATTLER_DOMAIN,
    BATTLE_SCRIPT_REMAININGHPTOPOWER_BRANCH_CENSUS, BATTLE_SCRIPT_REMAININGHPTOPOWER_CASES,
    BATTLE_SCRIPT_REMAININGHPTOPOWER_CATEGORY_CENSUS,
    BATTLE_SCRIPT_REMAININGHPTOPOWER_DOMAIN_CENSUS,
    BATTLE_SCRIPT_REMAININGHPTOPOWER_DYNAMIC_BASE_POWER_EDGE_DOMAIN,
    BATTLE_SCRIPT_REMAININGHPTOPOWER_MAX_HP_DOMAIN,
    BATTLE_SCRIPT_REMAININGHPTOPOWER_OPTIONAL_BATTLER_DOMAIN,
    BATTLE_SCRIPT_REMAININGHPTOPOWER_POWER_REPRESENTATIVE_HP_DOMAIN,
    BATTLE_SCRIPT_REMAININGHPTOPOWER_POWER_TABLE,
    BATTLE_SCRIPT_REMAININGHPTOPOWER_TRANSITION_THRESHOLDS,
    BATTLE_SCRIPT_REMAININGHPTOPOWER_VECTOR_CORPUS_SHA256,
};

fn rules(value: BattleScriptRemaininghptopowerVectorState) -> BattleScriptRemaininghptopowerRules {
    BattleScriptRemaininghptopowerRules {
        battlers: core::array::from_fn(|index| BattleScriptRemaininghptopowerBattlerState {
            hp: value.hp[index],
            max_hp: value.max_hp[index],
        }),
        dynamic_base_power: value.dynamic_base_power,
        selector_roles: BattleScriptRemaininghptopowerRoles {
            attacker: value.attacker,
            target: value.target,
            effect_battler: value.effect_battler,
            fainted: value.fainted,
        },
    }
}

fn vector_state(
    value: BattleScriptRemaininghptopowerRules,
) -> BattleScriptRemaininghptopowerVectorState {
    BattleScriptRemaininghptopowerVectorState {
        hp: value.battlers.map(|battler| battler.hp),
        max_hp: value.battlers.map(|battler| battler.max_hp),
        dynamic_base_power: value.dynamic_base_power,
        attacker: value.selector_roles.attacker,
        target: value.selector_roles.target,
        effect_battler: value.selector_roles.effect_battler,
        fainted: value.selector_roles.fainted,
    }
}

#[test]
fn complete_projected_outputs_controls_and_exact_missing_role_errors_match_canonical_typescript() {
    assert_eq!(BATTLE_SCRIPT_REMAININGHPTOPOWER_CASES.len(), 888);
    for (case_index, case) in BATTLE_SCRIPT_REMAININGHPTOPOWER_CASES.iter().enumerate() {
        execute_case(case_index, case);
    }
}

fn execute_case(case_index: usize, case: &BattleScriptRemaininghptopowerVectorCase) {
    let input = rules(case.initial);
    let before = input;
    let mut current = input;
    let mut actual_controls = Vec::new();
    let mut actual_error = None;

    for application in 0..case.applications {
        let prior = current;
        match apply_battle_script_remaininghptopower(&current) {
            Ok(outcome) => {
                actual_controls.push(outcome.control);
                assert_transition_shape(
                    case_index,
                    case,
                    application,
                    prior,
                    outcome.rules,
                    outcome.control,
                );
                current = outcome.rules;
            }
            Err(error) => {
                actual_error = Some(error.to_string());
                break;
            }
        }
    }

    assert_eq!(
        input, before,
        "case {case_index} {}: native transformation mutated input",
        case.label,
    );
    match (actual_error, case.expected, case.expected_error) {
        (None, Some(expected), None) => {
            assert_eq!(
                actual_controls.as_slice(),
                case.controls,
                "case {case_index} {}: canonical control sequence",
                case.label,
            );
            assert_eq!(
                actual_controls.len(),
                usize::from(case.applications),
                "case {case_index} {}: successful sequence stopped early",
                case.label,
            );
            assert_eq!(
                vector_state(current),
                expected,
                "case {case_index} {}: complete projected output",
                case.label,
            );
        }
        (Some(error), None, Some(expected_error)) => {
            assert_eq!(
                actual_controls.as_slice(),
                case.controls,
                "case {case_index} {}: error must not produce control",
                case.label,
            );
            assert_eq!(
                error, expected_error,
                "case {case_index} {}: exact ordered role error",
                case.label,
            );
        }
        (error, expected, expected_error) => panic!(
            "case {case_index} {}: generated outcome shape disagrees with native result: error={error:?}, expected={expected:?}, expected_error={expected_error:?}",
            case.label,
        ),
    }
}

fn assert_transition_shape(
    case_index: usize,
    case: &BattleScriptRemaininghptopowerVectorCase,
    application: u8,
    prior: BattleScriptRemaininghptopowerRules,
    next: BattleScriptRemaininghptopowerRules,
    control: BattleScriptRemaininghptopowerControl,
) {
    assert_eq!(
        control,
        BattleScriptRemaininghptopowerControl::Advance,
        "case {case_index} {} application {application}: command must advance",
        case.label,
    );
    let attacker = prior.selector_roles.attacker.unwrap_or_else(|| {
        panic!(
            "case {case_index} {} application {application}: advance had no attacker",
            case.label,
        )
    });
    let attacker_state = prior.battlers[attacker.index()];
    let expected_power = remaining_hp_to_power(attacker_state.hp, attacker_state.max_hp)
        .unwrap_or_else(|error| {
            panic!(
                "case {case_index} {} application {application}: legal generated HP state failed: {error}",
                case.label,
            )
        });
    assert_eq!(
        next.battlers, prior.battlers,
        "case {case_index} {} application {application}: changed HP/maxHP sibling projection",
        case.label,
    );
    assert_eq!(
        next.selector_roles, prior.selector_roles,
        "case {case_index} {} application {application}: changed selector roles",
        case.label,
    );
    assert_eq!(
        next.dynamic_base_power, expected_power,
        "case {case_index} {} application {application}: did not overwrite only dynamic base power",
        case.label,
    );
}

#[test]
fn exact_fraction_matrix_retains_every_inclusive_power_threshold_and_living_minimum_correction() {
    let exact = BATTLE_SCRIPT_REMAININGHPTOPOWER_CASES
        .iter()
        .filter(|case| case.category == "all-scaled-fractions-maxhp-48")
        .collect::<Vec<_>>();
    assert_eq!(exact.len(), 49);

    for hp in 0_u16..=BATTLE_SCRIPT_REMAININGHPTOPOWER_SCALE {
        let case = exact
            .iter()
            .find(|case| {
                let attacker = case.initial.attacker.expect("exact fraction attacker");
                case.initial.hp[attacker.index()] == hp
                    && case.initial.max_hp[attacker.index()]
                        == BATTLE_SCRIPT_REMAININGHPTOPOWER_SCALE
            })
            .unwrap_or_else(|| panic!("missing exact scaled-fraction case {hp}"));
        let fraction = get_scaled_hp_fraction(hp, BATTLE_SCRIPT_REMAININGHPTOPOWER_SCALE)
            .expect("positive maxHP exact fraction");
        assert_eq!(fraction, u32::from(hp));
        let expected = case.expected.expect("exact fraction expected state");
        assert_eq!(
            expected.dynamic_base_power,
            source_table_power(fraction),
            "exact scaled fraction {fraction}",
        );
    }

    for (index, &(threshold, power)) in BATTLE_SCRIPT_FLAIL_HP_SCALE_TO_POWER.iter().enumerate() {
        assert_eq!(
            BATTLE_SCRIPT_REMAININGHPTOPOWER_POWER_TABLE[index],
            (threshold, power)
        );
        assert_eq!(
            remaining_hp_to_power(u16::from(threshold), BATTLE_SCRIPT_REMAININGHPTOPOWER_SCALE)
                .expect("table threshold is legal"),
            power,
            "threshold {threshold} must be inclusive",
        );
        if let Some(&(next_threshold, next_power)) =
            BATTLE_SCRIPT_FLAIL_HP_SCALE_TO_POWER.get(index + 1)
        {
            assert_eq!(
                remaining_hp_to_power(u16::from(threshold) + 1, BATTLE_SCRIPT_REMAININGHPTOPOWER_SCALE)
                    .expect("following table fraction is legal"),
                next_power,
                "first fraction after inclusive threshold {threshold} must enter the next {next_threshold} band",
            );
        }
    }
    assert_eq!(
        get_scaled_hp_fraction(1, u16::MAX).expect("living minimum denominator"),
        1,
        "1/maxHP must use GetScaledHPFraction's zero-to-one correction",
    );
    assert_eq!(
        remaining_hp_to_power(0, u16::MAX).expect("fainted HP is still defined"),
        200
    );
    assert_eq!(
        remaining_hp_to_power(u16::MAX, u16::MAX).expect("full HP"),
        20
    );
}

fn source_table_power(fraction: u32) -> u16 {
    BATTLE_SCRIPT_FLAIL_HP_SCALE_TO_POWER
        .iter()
        .find_map(|&(threshold, power)| (fraction <= u32::from(threshold)).then_some(power))
        .unwrap_or_else(|| panic!("legal source fraction {fraction} escaped Flail table"))
}

#[test]
fn varied_maxhp_partitions_and_u16_edges_cover_both_sides_of_every_representable_transition() {
    let partitions = BATTLE_SCRIPT_REMAININGHPTOPOWER_CASES
        .iter()
        .filter(|case| case.category == "varied-maxhp-threshold-partitions")
        .collect::<Vec<_>>();
    assert_eq!(partitions.len(), 100);
    for max_hp in BATTLE_SCRIPT_REMAININGHPTOPOWER_MAX_HP_DOMAIN {
        for threshold in BATTLE_SCRIPT_REMAININGHPTOPOWER_TRANSITION_THRESHOLDS {
            let first_after = (u32::from(threshold + 1) * u32::from(max_hp)
                + u32::from(BATTLE_SCRIPT_REMAININGHPTOPOWER_SCALE - 1))
                / u32::from(BATTLE_SCRIPT_REMAININGHPTOPOWER_SCALE);
            assert!(first_after <= u32::from(max_hp));
            let before_hp = u16::try_from(first_after - 1).expect("u16 partition before");
            let after_hp = u16::try_from(first_after).expect("u16 partition after");
            let find = |hp| {
                partitions
                    .iter()
                    .find(|case| {
                        let attacker = case.initial.attacker.expect("partition attacker");
                        case.initial.max_hp[attacker.index()] == max_hp
                            && case.initial.hp[attacker.index()] == hp
                    })
                    .unwrap_or_else(|| {
                        panic!("missing maxHP {max_hp}, threshold {threshold}, hp {hp}")
                    })
            };
            let before = find(before_hp);
            let after = find(after_hp);
            let before_fraction =
                get_scaled_hp_fraction(before_hp, max_hp).expect("before legal HP");
            let after_fraction = get_scaled_hp_fraction(after_hp, max_hp).expect("after legal HP");
            assert!(before_fraction <= u32::from(threshold));
            assert!(after_fraction > u32::from(threshold));
            assert_ne!(
                before.expected.expect("before output").dynamic_base_power,
                after.expected.expect("after output").dynamic_base_power,
                "maxHP {max_hp} threshold {threshold} must cross a power band",
            );
        }
    }
    assert_eq!(
        BATTLE_SCRIPT_REMAININGHPTOPOWER_MAX_HP_DOMAIN,
        [1, 2, 3, 47, 48, 49, 100, 999, 32767, u16::MAX],
    );
}

#[test]
fn attacker_aliases_full_selector_cross_product_prior_power_and_repeat_behavior_are_preserved() {
    let selector_matrix = BATTLE_SCRIPT_REMAININGHPTOPOWER_CASES
        .iter()
        .filter(|case| case.category == "all-attacker-and-selector-role-combinations")
        .collect::<Vec<_>>();
    assert_eq!(selector_matrix.len(), 500);
    let observed = selector_matrix
        .iter()
        .map(|case| {
            (
                case.initial
                    .attacker
                    .expect("selector matrix attacker")
                    .as_u8(),
                case.initial
                    .target
                    .map(BattleScriptRemaininghptopowerBattler::as_u8),
                case.initial
                    .effect_battler
                    .map(BattleScriptRemaininghptopowerBattler::as_u8),
                case.initial
                    .fainted
                    .map(BattleScriptRemaininghptopowerBattler::as_u8),
            )
        })
        .collect::<BTreeSet<_>>();
    let expected = BATTLE_SCRIPT_REMAININGHPTOPOWER_BATTLER_DOMAIN
        .into_iter()
        .flat_map(|attacker| {
            BATTLE_SCRIPT_REMAININGHPTOPOWER_OPTIONAL_BATTLER_DOMAIN
                .into_iter()
                .flat_map(move |target| {
                    BATTLE_SCRIPT_REMAININGHPTOPOWER_OPTIONAL_BATTLER_DOMAIN
                        .into_iter()
                        .flat_map(move |effect_battler| {
                            BATTLE_SCRIPT_REMAININGHPTOPOWER_OPTIONAL_BATTLER_DOMAIN
                                .into_iter()
                                .map(move |fainted| (attacker, target, effect_battler, fainted))
                        })
                })
        })
        .collect::<BTreeSet<_>>();
    assert_eq!(observed, expected);

    let prior_dynamic = BATTLE_SCRIPT_REMAININGHPTOPOWER_CASES
        .iter()
        .filter(|case| case.category == "prior-dynamic-base-power-overwrite-matrix")
        .collect::<Vec<_>>();
    assert_eq!(prior_dynamic.len(), 60);
    for attacker in BATTLE_SCRIPT_REMAININGHPTOPOWER_BATTLER_DOMAIN {
        let observed_prior = prior_dynamic
            .iter()
            .filter(|case| {
                case.initial
                    .attacker
                    .map(BattleScriptRemaininghptopowerBattler::as_u8)
                    == Some(attacker)
            })
            .map(|case| case.initial.dynamic_base_power)
            .collect::<BTreeSet<_>>();
        assert_eq!(
            observed_prior,
            BATTLE_SCRIPT_REMAININGHPTOPOWER_DYNAMIC_BASE_POWER_EDGE_DOMAIN
                .into_iter()
                .collect(),
            "attacker {attacker}: every prior dynamic power must be overwritten",
        );
    }

    let repeated = BATTLE_SCRIPT_REMAININGHPTOPOWER_CASES
        .iter()
        .filter(|case| case.category == "repeated-application-idempotence")
        .collect::<Vec<_>>();
    assert_eq!(repeated.len(), 24);
    for case in repeated {
        assert_eq!(case.applications, 2);
        assert_eq!(
            case.controls,
            &[
                BattleScriptRemaininghptopowerControl::Advance,
                BattleScriptRemaininghptopowerControl::Advance,
            ],
            "{} must advance twice",
            case.label,
        );
        let expected = case.expected.expect("repeated output");
        let attacker = case.initial.attacker.expect("repeated attacker");
        assert_eq!(
            expected.dynamic_base_power,
            remaining_hp_to_power(
                case.initial.hp[attacker.index()],
                case.initial.max_hp[attacker.index()],
            )
            .expect("repeated legal HP"),
        );
    }
    assert_eq!(
        BATTLE_SCRIPT_REMAININGHPTOPOWER_POWER_REPRESENTATIVE_HP_DOMAIN,
        [0, 2, 5, 10, 17, 33],
    );
}

#[test]
fn missing_attacker_precedes_hp_reads_and_source_domains_constants_and_census_are_retained() {
    let missing = BATTLE_SCRIPT_REMAININGHPTOPOWER_CASES
        .iter()
        .filter(|case| case.category == "missing-attacker-before-hp-and-selector-reads")
        .collect::<Vec<_>>();
    assert_eq!(missing.len(), 125);
    assert!(missing.iter().all(|case| {
        case.initial.attacker.is_none()
            && case.expected.is_none()
            && case.controls.is_empty()
            && case.expected_error
                == Some("Battle Script hit-chain command requires a attacker role")
    }));
    let missing_roles = missing
        .iter()
        .map(|case| {
            (
                case.initial
                    .target
                    .map(BattleScriptRemaininghptopowerBattler::as_u8),
                case.initial
                    .effect_battler
                    .map(BattleScriptRemaininghptopowerBattler::as_u8),
                case.initial
                    .fainted
                    .map(BattleScriptRemaininghptopowerBattler::as_u8),
            )
        })
        .collect::<BTreeSet<_>>();
    assert_eq!(missing_roles.len(), 125);

    assert_eq!(BATTLE_SCRIPT_REMAININGHPTOPOWER_BATTLER_COUNT, 4);
    assert_eq!(
        BATTLE_SCRIPT_REMAININGHPTOPOWER_BATTLERS.map(BattleScriptRemaininghptopowerBattler::as_u8),
        BATTLE_SCRIPT_REMAININGHPTOPOWER_BATTLER_DOMAIN,
    );
    assert_eq!(BATTLE_SCRIPT_REMAININGHPTOPOWER_SCALE, 48);
    assert_eq!(
        BATTLE_SCRIPT_FLAIL_HP_SCALE_TO_POWER,
        [(1, 200), (4, 150), (9, 100), (16, 80), (32, 40), (48, 20)],
    );
    assert_eq!(
        BATTLE_SCRIPT_REMAININGHPTOPOWER_DOMAIN_CENSUS,
        [
            ("battler-slots", 4),
            ("attacker-role-values", 4),
            ("optional-role-values", 5),
            ("retained-selector-role-fields", 4),
            ("attacker-selector-cross-product", 500),
            ("hp-u16-values", 65536),
            ("maxhp-u16-positive-values", 65535),
            ("legal-hp-maxhp-state-space", 2_147_516_415),
            ("scaled-fraction-values-at-maxhp-48", 49),
            ("flail-power-bands", 6),
            ("power-transition-thresholds", 5),
            ("varied-maxhp-values", 10),
            ("dynamic-base-power-u16-values", 65536),
            ("dynamic-base-power-edge-values", 15),
            ("application-count-values", 2),
            ("missing-attacker-selector-combinations", 125),
        ],
    );
    assert_eq!(
        BATTLE_SCRIPT_REMAININGHPTOPOWER_CATEGORY_CENSUS,
        [
            ("all-attacker-and-selector-role-combinations", 500),
            ("all-scaled-fractions-maxhp-48", 49),
            ("hp-zero-living-min-full-varied-maxhp", 30),
            ("missing-attacker-before-hp-and-selector-reads", 125),
            ("prior-dynamic-base-power-overwrite-matrix", 60),
            ("repeated-application-idempotence", 24),
            ("varied-maxhp-threshold-partitions", 100),
        ],
    );
    assert_eq!(
        BATTLE_SCRIPT_REMAININGHPTOPOWER_BRANCH_CENSUS,
        [
            ("missing-attacker-role", 125),
            ("write-power-100-advance", 114),
            ("write-power-100-then-100-advance", 4),
            ("write-power-150-advance", 111),
            ("write-power-150-then-150-advance", 4),
            ("write-power-20-advance", 130),
            ("write-power-20-then-20-advance", 4),
            ("write-power-200-advance", 131),
            ("write-power-200-then-200-advance", 4),
            ("write-power-40-advance", 132),
            ("write-power-40-then-40-advance", 4),
            ("write-power-80-advance", 121),
            ("write-power-80-then-80-advance", 4),
        ],
    );
    assert_eq!(
        BATTLE_SCRIPT_REMAININGHPTOPOWER_VECTOR_CORPUS_SHA256,
        "d6c872d3676d7029e4cb8a6448b77b6ce8d2a36b799af3fc3ed9f4956bb531fa",
    );
}

#[test]
fn hp_u16_arithmetic_is_widened_and_missing_attacker_precedes_malformed_hp_validation() {
    assert_eq!(
        get_scaled_hp_fraction(u16::MAX, 1).expect("nonzero source-width maxHP"),
        3_145_680,
        "u16 hp * scale must not overflow before the floor division",
    );
    assert_eq!(
        remaining_hp_to_power(u16::MAX, 1)
            .expect_err("over-max HP cannot select a legal Flail table entry")
            .to_string(),
        "GetScaledHPFraction produced out-of-range Flail fraction 3145680",
    );

    let malformed = BattleScriptRemaininghptopowerRules {
        battlers: [
            BattleScriptRemaininghptopowerBattlerState { hp: 1, max_hp: 0 },
            BattleScriptRemaininghptopowerBattlerState { hp: 0, max_hp: 1 },
            BattleScriptRemaininghptopowerBattlerState { hp: 1, max_hp: 1 },
            BattleScriptRemaininghptopowerBattlerState { hp: u16::MAX, max_hp: u16::MAX },
        ],
        dynamic_base_power: u16::MAX,
        selector_roles: BattleScriptRemaininghptopowerRoles {
            attacker: None,
            target: Some(BattleScriptRemaininghptopowerBattler::Battler3),
            effect_battler: Some(BattleScriptRemaininghptopowerBattler::Battler2),
            fainted: Some(BattleScriptRemaininghptopowerBattler::Battler1),
        },
    };
    let before = malformed;
    assert_eq!(
        apply_battle_script_remaininghptopower(&malformed)
            .expect_err("missing attacker must win before maxHP validation")
            .to_string(),
        "Battle Script hit-chain command requires a attacker role",
    );
    assert_eq!(
        malformed, before,
        "failed ordered role resolution mutated input"
    );
}
